#![allow(unused)]
use prusti_contracts::*;

/// Given a non‐empty vector `x` of 8‐bit signed integers,
/// returns a 2‐element vector `[min, max]` such that:
///   1. `min <= max`
///   2. Every element of `x` lies between `min` and `max` (inclusive).
///   3. Both `min` and `max` actually occur in `x`.
#[trusted] 
#[requires(x.len() > 0)]
#[ensures(result.len() == 2)]
#[ensures(result[0] <= result[1])]
#[ensures(forall(|i: usize| i < x.len() ==> result[0] <= x[i] && x[i] <= result[1]))]
#[ensures(exists(|i: usize| i < x.len() && x[i] == result[0]))]
#[ensures(exists(|i: usize| i < x.len() && x[i] == result[1]))]
fn getdomain(x: Vec<i8>) -> Vec<i8> {
    // Since x.len() > 0, it is safe to index at 0
    let mut mn: i8 = x[0];
    let mut mx: i8 = x[0];
    let mut i: usize = 1;
    // Scan the rest of the vector to update min and max
    while i < x.len() {
        let v = x[i];
        if v < mn {
            mn = v;
        }
        if v > mx {
            mx = v;
        }
        i += 1;
    }
    // Return a 2-element vector [min, max]
    vec![mn, mx]
}